create or replace function public.claim_sync_work(p_organization_id uuid,p_agent_id text,p_connector_version text,p_interval_seconds integer default 300)returns table(run_id uuid,request_id uuid,trigger_type text,should_execute boolean)language plpgsql security definer set search_path=public as $$declare v_run uuid;v_request uuid;v_trigger text;v_last_auto timestamptz;begin perform pg_advisory_xact_lock(hashtextextended('sync-control:'||p_organization_id::text,0));update sync_runs set status='FAILED',completed_at=now(),duration_ms=extract(epoch from(now()-started_at))*1000,failure_reason='STALE_RUN_LEASE_EXPIRED'where organization_id=p_organization_id and status='RUNNING'and started_at<now()-interval'20 minutes';update sync_refresh_requests r set status='FAILED',completed_at=now(),failure_reason='STALE_RUN_LEASE_EXPIRED'where r.organization_id=p_organization_id and r.status='RUNNING'and not exists(select 1 from sync_runs s where s.id=r.sync_run_id and s.status='RUNNING');if exists(select 1 from sync_runs s where s.organization_id=p_organization_id and s.status='RUNNING')then insert into sync_runs(organization_id,trigger_type,status,requested_at,completed_at,agent_id,connector_version,failure_reason)values(p_organization_id,'AUTOMATIC','SKIPPED_ALREADY_RUNNING',now(),now(),p_agent_id,p_connector_version,'ACTIVE_RUN_EXISTS')returning id into v_run;return query select v_run,null::uuid,'AUTOMATIC'::text,false;return;end if;select r.id into v_request from sync_refresh_requests r where r.organization_id=p_organization_id and r.status='QUEUED'order by r.requested_at limit 1 for update skip locked;if v_request is not null then v_trigger:='MANUAL';else select max(s.requested_at)into v_last_auto from sync_runs s where s.organization_id=p_organization_id and s.trigger_type='AUTOMATIC'and s.status in('RUNNING','SUCCESS','FAILED');if v_last_auto is not null and v_last_auto>now()-make_interval(secs=>greatest(60,p_interval_seconds))then return;end if;v_trigger:='AUTOMATIC';end if;insert into sync_runs(organization_id,refresh_request_id,trigger_type,status,requested_at,started_at,agent_id,connector_version)values(p_organization_id,v_request,v_trigger,'RUNNING',now(),now(),p_agent_id,p_connector_version)returning id into v_run;if v_request is not null then update sync_refresh_requests set status='RUNNING',started_at=now(),sync_run_id=v_run where id=v_request;end if;return query select v_run,v_request,v_trigger,true;end$$;
revoke all on function public.claim_sync_work(uuid,text,text,integer)from public,anon,authenticated;grant execute on function public.claim_sync_work(uuid,text,text,integer)to service_role;
